/*
 * kmem.c
 *
 * WDM kernel driver that maps a user buffer and services read/write requests
 * for a caller-chosen virtual address range.
 *
 * Device : \\Device\\KMem  (symlink: \\DosDevices\\KMem  ->  \\.\KMem)
 *
 * IOCTL protocol (METHOD_BUFFERED):
 *
 *   IOCTL_KMEM_READ
 *     In  : KMEM_REQUEST  { Address, Size }
 *     Out : Size bytes copied from Address
 *
 *   IOCTL_KMEM_WRITE
 *     In  : KMEM_REQUEST  { Address, Size }  followed immediately by
 *           Size bytes of payload to write to Address
 *     Out : none
 *
 * Reads  use MmCopyMemory  (non-fatal on bad address; requires Win 8.1+).
 * Writes use an MDL remapping so read-only PTEs are bypassed; falls back
 * to a guarded RtlCopyMemory for non-pageable kernel addresses.
 *
 * Build: add to a WDK 10 project targeting x64, /W4, Kernel mode.
 */

#include <ntddk.h>

/* --------------------------------------------------------------------------
 * Tunables
 * -------------------------------------------------------------------------- */

#define KMEM_MAX_TRANSFER   (4UL * 1024UL * 1024UL)    /* 4 MiB hard cap    */

/* --------------------------------------------------------------------------
 * Device names
 * -------------------------------------------------------------------------- */

#define KMEM_DEVICE_NAME    L"\\Device\\KMem"
#define KMEM_SYMLINK_NAME   L"\\DosDevices\\KMem"

/* --------------------------------------------------------------------------
 * IOCTL codes
 * -------------------------------------------------------------------------- */

#define KMEM_DEVICE_TYPE    FILE_DEVICE_UNKNOWN

#define IOCTL_KMEM_READ  \
    CTL_CODE(KMEM_DEVICE_TYPE, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_KMEM_WRITE \
    CTL_CODE(KMEM_DEVICE_TYPE, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)

/* --------------------------------------------------------------------------
 * Shared request header (same layout consumed from user mode)
 * -------------------------------------------------------------------------- */

#pragma pack(push, 1)
typedef struct _KMEM_REQUEST {
    ULONG64 Address;    /* virtual address in the target space            */
    ULONG   Size;       /* byte count; must be in [1, KMEM_MAX_TRANSFER]  */
} KMEM_REQUEST, *PKMEM_REQUEST;
#pragma pack(pop)

/* --------------------------------------------------------------------------
 * Globals
 * -------------------------------------------------------------------------- */

static PDEVICE_OBJECT g_Device = NULL;

/* --------------------------------------------------------------------------
 * KmemRead
 *
 * Copy Size bytes from the virtual address Address into Dest.
 * Uses MmCopyMemory so a non-present or guarded page returns a failure
 * status rather than a bugcheck.
 * -------------------------------------------------------------------------- */
_IRQL_requires_max_(APC_LEVEL)
static NTSTATUS
KmemRead(
    _In_                      ULONG64 Address,
    _Out_writes_bytes_(Size)  PVOID   Dest,
    _In_                      ULONG   Size,
    _Out_                     PULONG  BytesCopied
)
{
    MM_COPY_ADDRESS src;
    SIZE_T          copied = 0;
    NTSTATUS        status;

    *BytesCopied = 0;

    src.VirtualAddress = (PVOID)(ULONG_PTR)Address;

    status = MmCopyMemory(
        Dest,
        src,
        (SIZE_T)Size,
        MM_COPY_MEMORY_VIRTUAL,
        &copied
    );

    *BytesCopied = (ULONG)copied;
    return status;
}

/* --------------------------------------------------------------------------
 * KmemWrite
 *
 * Copy Size bytes from Src to the virtual address Address.
 *
 * Strategy:
 *   1.  Build an MDL over the target range and remap it as kernel-writable.
 *       This allows writes through copy-on-write or read-only PTEs.
 *   2.  If MDL locking fails (e.g. address is non-paged kernel memory that
 *       MmProbeAndLockPages refuses), fall back to a __try-guarded
 *       RtlCopyMemory directly into the kernel virtual address.
 * -------------------------------------------------------------------------- */
_IRQL_requires_max_(APC_LEVEL)
static NTSTATUS
KmemWrite(
    _In_                     ULONG64     Address,
    _In_reads_bytes_(Size)   const VOID *Src,
    _In_                     ULONG       Size
)
{
    PMDL            mdl     = NULL;
    PVOID           mapped  = NULL;
    BOOLEAN         locked  = FALSE;
    KPROCESSOR_MODE mode;
    NTSTATUS        status  = STATUS_SUCCESS;

    /* Determine probe mode from address range.
     * MmHighestUserAddress is a pointer exported by ntddk; dereference it. */
    mode = ((ULONG_PTR)Address <= (ULONG_PTR)MmHighestUserAddress)
           ? UserMode
           : KernelMode;

    __try {
        mdl = IoAllocateMdl(
            (PVOID)(ULONG_PTR)Address,
            Size,
            FALSE,
            FALSE,
            NULL
        );
        if (mdl == NULL) {
            status = STATUS_INSUFFICIENT_RESOURCES;
            __leave;
        }

        MmProbeAndLockPages(mdl, mode, IoWriteAccess);
        locked = TRUE;

        mapped = MmMapLockedPagesSpecifyCache(
            mdl,
            KernelMode,
            MmNonCached,
            NULL,
            FALSE,
            NormalPagePriority | MdlMappingNoExecute
        );

        if (mapped == NULL) {
            status = STATUS_INSUFFICIENT_RESOURCES;
            __leave;
        }

        RtlCopyMemory(mapped, Src, (SIZE_T)Size);
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        status = GetExceptionCode();
    }

    /* Ordered teardown regardless of which path was taken above. */
    if (mapped != NULL) {
        MmUnmapLockedPages(mapped, mdl);
        mapped = NULL;
    }
    if (locked) {
        MmUnlockPages(mdl);
        locked = FALSE;
    }
    if (mdl != NULL) {
        IoFreeMdl(mdl);
        mdl = NULL;
    }

    /* Fallback: MDL path rejected the kernel address (e.g. non-paged pool).
     * Attempt a plain copy under a structured exception handler. */
    if (!NT_SUCCESS(status) && mode == KernelMode) {
        __try {
            RtlCopyMemory((PVOID)(ULONG_PTR)Address, Src, (SIZE_T)Size);
            status = STATUS_SUCCESS;
        }
        __except (EXCEPTION_EXECUTE_HANDLER) {
            status = GetExceptionCode();
        }
    }

    return status;
}

/* --------------------------------------------------------------------------
 * IRP_MJ_CREATE / IRP_MJ_CLOSE
 * -------------------------------------------------------------------------- */
static NTSTATUS
KmemDispatchCreateClose(
    _In_    PDEVICE_OBJECT DeviceObject,
    _Inout_ PIRP           Irp
)
{
    UNREFERENCED_PARAMETER(DeviceObject);

    Irp->IoStatus.Status      = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

/* --------------------------------------------------------------------------
 * IRP_MJ_DEVICE_CONTROL
 * -------------------------------------------------------------------------- */
static NTSTATUS
KmemDispatchControl(
    _In_    PDEVICE_OBJECT DeviceObject,
    _Inout_ PIRP           Irp
)
{
    PIO_STACK_LOCATION  stack;
    PVOID               buf;
    ULONG               inLen, outLen, code;
    PKMEM_REQUEST       req;
    ULONG64             addr;
    ULONG               size;
    ULONG               copied;
    NTSTATUS            status = STATUS_INVALID_PARAMETER;
    ULONG_PTR           info   = 0;

    UNREFERENCED_PARAMETER(DeviceObject);

    stack  = IoGetCurrentIrpStackLocation(Irp);
    code   = stack->Parameters.DeviceIoControl.IoControlCode;
    inLen  = stack->Parameters.DeviceIoControl.InputBufferLength;
    outLen = stack->Parameters.DeviceIoControl.OutputBufferLength;
    buf    = Irp->AssociatedIrp.SystemBuffer;   /* METHOD_BUFFERED */

    switch (code) {

    /* ------------------------------------------------------------------
     * IOCTL_KMEM_READ
     *   Input  (inLen)  >= sizeof(KMEM_REQUEST)
     *   Output (outLen) >= req->Size
     *   The system buffer is big enough for the larger of the two; we
     *   read the header fields into locals before overwriting the buffer
     *   with the result bytes.
     * ------------------------------------------------------------------ */
    case IOCTL_KMEM_READ:

        if (inLen < sizeof(KMEM_REQUEST)) {
            status = STATUS_BUFFER_TOO_SMALL;
            break;
        }

        req  = (PKMEM_REQUEST)buf;
        addr = req->Address;
        size = req->Size;

        if (size == 0 || size > KMEM_MAX_TRANSFER) {
            status = STATUS_INVALID_PARAMETER;
            break;
        }
        if (outLen < size) {
            status = STATUS_BUFFER_TOO_SMALL;
            break;
        }

        copied = 0;
        status = KmemRead(addr, buf, size, &copied);
        info   = (ULONG_PTR)copied;
        break;

    /* ------------------------------------------------------------------
     * IOCTL_KMEM_WRITE
     *   Input (inLen) >= sizeof(KMEM_REQUEST) + req->Size
     *   Payload bytes begin immediately after the header in the buffer.
     * ------------------------------------------------------------------ */
    case IOCTL_KMEM_WRITE:

        if (inLen < sizeof(KMEM_REQUEST)) {
            status = STATUS_BUFFER_TOO_SMALL;
            break;
        }

        req  = (PKMEM_REQUEST)buf;
        addr = req->Address;
        size = req->Size;

        if (size == 0 || size > KMEM_MAX_TRANSFER) {
            status = STATUS_INVALID_PARAMETER;
            break;
        }

        /* Guard against integer overflow in the length check. */
        if (size > ULONG_MAX - (ULONG)sizeof(KMEM_REQUEST) ||
            inLen < sizeof(KMEM_REQUEST) + size) {
            status = STATUS_BUFFER_TOO_SMALL;
            break;
        }

        status = KmemWrite(
            addr,
            (const UCHAR *)buf + sizeof(KMEM_REQUEST),
            size
        );
        info = 0;
        break;

    default:
        status = STATUS_INVALID_DEVICE_REQUEST;
        break;
    }

    Irp->IoStatus.Status      = status;
    Irp->IoStatus.Information = info;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return status;
}

/* --------------------------------------------------------------------------
 * DriverUnload
 * -------------------------------------------------------------------------- */
static VOID
KmemUnload(
    _In_ PDRIVER_OBJECT DriverObject
)
{
    UNICODE_STRING symlink;

    UNREFERENCED_PARAMETER(DriverObject);

    RtlInitUnicodeString(&symlink, KMEM_SYMLINK_NAME);
    IoDeleteSymbolicLink(&symlink);

    if (g_Device != NULL) {
        IoDeleteDevice(g_Device);
        g_Device = NULL;
    }
}

/* --------------------------------------------------------------------------
 * DriverEntry
 * -------------------------------------------------------------------------- */
NTSTATUS
DriverEntry(
    _In_ PDRIVER_OBJECT  DriverObject,
    _In_ PUNICODE_STRING RegistryPath
)
{
    UNICODE_STRING devName, symlink;
    NTSTATUS       status;

    UNREFERENCED_PARAMETER(RegistryPath);

    RtlInitUnicodeString(&devName, KMEM_DEVICE_NAME);
    RtlInitUnicodeString(&symlink, KMEM_SYMLINK_NAME);

    status = IoCreateDevice(
        DriverObject,
        0,                      /* no device extension needed   */
        &devName,
        KMEM_DEVICE_TYPE,
        FILE_DEVICE_SECURE_OPEN,
        FALSE,                  /* not exclusive                */
        &g_Device
    );
    if (!NT_SUCCESS(status)) {
        return status;
    }

    /* METHOD_BUFFERED does not require DO_DIRECT_IO; just clear the
     * initializing flag so the device is immediately accessible. */
    g_Device->Flags &= ~DO_DEVICE_INITIALIZING;

    status = IoCreateSymbolicLink(&symlink, &devName);
    if (!NT_SUCCESS(status)) {
        IoDeleteDevice(g_Device);
        g_Device = NULL;
        return status;
    }

    DriverObject->DriverUnload                          = KmemUnload;
    DriverObject->MajorFunction[IRP_MJ_CREATE]         = KmemDispatchCreateClose;
    DriverObject->MajorFunction[IRP_MJ_CLOSE]          = KmemDispatchCreateClose;
    DriverObject->MajorFunction[IRP_MJ_DEVICE_CONTROL] = KmemDispatchControl;

    return STATUS_SUCCESS;
}

/*
 * kmem.c — WDM kernel driver: cross-process virtual memory read/write
 *
 * Device : \Device\KMem
 * Symlink: \DosDevices\KMem
 *
 * IOCTLs (METHOD_BUFFERED):
 *
 *   IOCTL_KMEM_READ
 *     In  : KMEM_REQUEST
 *     Out : raw bytes read from Address in the target process
 *
 *   IOCTL_KMEM_WRITE
 *     In  : KMEM_REQUEST followed immediately by the bytes to write
 *     Out : none  (IoStatus.Information = bytes actually written)
 *
 * Both IOCTLs accept ProcessId == NULL to target the calling process.
 *
 * Build: WDK 10, x64, C, /W4 /WX
 */

#include <ntddk.h>
#include <wdm.h>

/* ── constants ─────────────────────────────────────────────────────────── */

#define DEVICE_NAME     L"\\Device\\KMem"
#define SYMLINK_NAME    L"\\DosDevices\\KMem"
#define KMEM_POOL_TAG   'meMK'

#define IOCTL_KMEM_READ  \
    CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_KMEM_WRITE \
    CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)

/* ── public request structure (share with user-mode callers) ───────────── */

typedef struct _KMEM_REQUEST {
    HANDLE  ProcessId;  /* target PID; NULL → caller's own process */
    PVOID   Address;    /* virtual address in that process          */
    SIZE_T  Size;       /* byte count to transfer                   */
} KMEM_REQUEST, *PKMEM_REQUEST;

/* ── MmCopyVirtualMemory (undocumented, stable since Vista) ────────────── */

NTSTATUS
NTAPI
MmCopyVirtualMemory(
    _In_  PEPROCESS         SourceProcess,
    _In_  PVOID             SourceAddress,
    _In_  PEPROCESS         TargetProcess,
    _Out_ PVOID             TargetAddress,
    _In_  SIZE_T            BufferSize,
    _In_  KPROCESSOR_MODE   PreviousMode,
    _Out_ PSIZE_T           ReturnSize
);

/* ── forward declarations ──────────────────────────────────────────────── */

static DRIVER_UNLOAD    KMemUnload;
static DRIVER_DISPATCH  KMemCreateClose;
static DRIVER_DISPATCH  KMemDeviceControl;

/* ── globals ───────────────────────────────────────────────────────────── */

static PDEVICE_OBJECT g_DeviceObject = NULL;

/* ── helpers ───────────────────────────────────────────────────────────── */

/*
 * Resolve a PID to a referenced PEPROCESS.
 * Returns the current process (also referenced) when pid is NULL.
 */
static NTSTATUS
KMemLookupProcess(
    _In_  HANDLE     Pid,
    _Out_ PEPROCESS *OutProcess
)
{
    if (Pid == NULL || Pid == PsGetCurrentProcessId()) {
        *OutProcess = PsGetCurrentProcess();
        ObReferenceObject(*OutProcess);
        return STATUS_SUCCESS;
    }
    return PsLookupProcessByProcessId(Pid, OutProcess);
}

/* ── IRP handlers ──────────────────────────────────────────────────────── */

static NTSTATUS
KMemUnload(
    _In_ PDRIVER_OBJECT DriverObject
)
{
    UNICODE_STRING symlink = RTL_CONSTANT_STRING(SYMLINK_NAME);
    IoDeleteSymbolicLink(&symlink);

    if (g_DeviceObject != NULL) {
        IoDeleteDevice(g_DeviceObject);
        g_DeviceObject = NULL;
    }

    UNREFERENCED_PARAMETER(DriverObject);
    return STATUS_SUCCESS;
}

/* Satisfy the DRIVER_UNLOAD typedef (void return) */
static VOID
KMemUnloadVoid(
    _In_ PDRIVER_OBJECT DriverObject
)
{
    KMemUnload(DriverObject);
}

static NTSTATUS
KMemCreateClose(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp
)
{
    UNREFERENCED_PARAMETER(DeviceObject);

    Irp->IoStatus.Status      = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

static NTSTATUS
KMemDeviceControl(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp
)
{
    UNREFERENCED_PARAMETER(DeviceObject);

    PIO_STACK_LOCATION stack  = IoGetCurrentIrpStackLocation(Irp);
    ULONG  code    = stack->Parameters.DeviceIoControl.IoControlCode;
    ULONG  inLen   = stack->Parameters.DeviceIoControl.InputBufferLength;
    ULONG  outLen  = stack->Parameters.DeviceIoControl.OutputBufferLength;
    PVOID  sysBuf  = Irp->AssociatedIrp.SystemBuffer;

    NTSTATUS status      = STATUS_INVALID_PARAMETER;
    SIZE_T   transferred = 0;

    switch (code) {

    /* ------------------------------------------------------------------ */
    case IOCTL_KMEM_READ: {
        /*
         * Caller supplies a KMEM_REQUEST as input.
         * The driver copies up to min(outLen, req.Size) bytes starting at
         * req.Address in req.ProcessId into the output portion of the
         * METHOD_BUFFERED system buffer.
         *
         * With METHOD_BUFFERED the kernel allocates one buffer of
         * max(inLen, outLen) bytes.  We capture all input fields before
         * writing to the buffer so the input and output regions can safely
         * overlap when outLen < sizeof(KMEM_REQUEST).
         */
        if (inLen < sizeof(KMEM_REQUEST)) {
            status = STATUS_BUFFER_TOO_SMALL;
            break;
        }

        /* Capture request fields before any write-back. */
        PKMEM_REQUEST req       = (PKMEM_REQUEST)sysBuf;
        HANDLE        pid       = req->ProcessId;
        PVOID         addr      = req->Address;
        SIZE_T        copySize  = min((SIZE_T)outLen, req->Size);

        if (copySize == 0) {
            status = STATUS_SUCCESS;
            break;
        }

        PEPROCESS targetProcess = NULL;
        status = KMemLookupProcess(pid, &targetProcess);
        if (!NT_SUCCESS(status)) break;

        /*
         * Stage the copy in a non-paged kernel buffer, then write the
         * result into sysBuf.  Staging avoids aliasing issues when the
         * target happens to be the current process and src/dst overlap.
         */
        PVOID staging = ExAllocatePoolWithTag(NonPagedPool, copySize, KMEM_POOL_TAG);
        if (staging == NULL) {
            ObDereferenceObject(targetProcess);
            status = STATUS_INSUFFICIENT_RESOURCES;
            break;
        }

        status = MmCopyVirtualMemory(
            targetProcess,          /* source process          */
            addr,                   /* source address          */
            PsGetCurrentProcess(),  /* destination process     */
            staging,                /* destination (kernel)    */
            copySize,
            KernelMode,
            &transferred
        );

        ObDereferenceObject(targetProcess);

        if (NT_SUCCESS(status) && transferred > 0) {
            RtlCopyMemory(sysBuf, staging, transferred);
        }

        ExFreePoolWithTag(staging, KMEM_POOL_TAG);
        break;
    }

    /* ------------------------------------------------------------------ */
    case IOCTL_KMEM_WRITE: {
        /*
         * Caller supplies a KMEM_REQUEST followed immediately by the bytes
         * to write.  The driver copies min(dataLen, req.Size) bytes from
         * that payload into req.Address in req.ProcessId.
         *
         * Input layout (all in sysBuf):
         *   [KMEM_REQUEST][... data bytes ...]
         */
        if (inLen < sizeof(KMEM_REQUEST)) {
            status = STATUS_BUFFER_TOO_SMALL;
            break;
        }

        PKMEM_REQUEST req      = (PKMEM_REQUEST)sysBuf;
        HANDLE        pid      = req->ProcessId;
        PVOID         addr     = req->Address;
        SIZE_T        dataLen  = (SIZE_T)inLen - sizeof(KMEM_REQUEST);
        PVOID         data     = (PUCHAR)sysBuf + sizeof(KMEM_REQUEST);
        SIZE_T        copySize = min(dataLen, req->Size);

        if (copySize == 0) {
            status = STATUS_SUCCESS;
            break;
        }

        PEPROCESS targetProcess = NULL;
        status = KMemLookupProcess(pid, &targetProcess);
        if (!NT_SUCCESS(status)) break;

        /*
         * Stage the payload so we have a stable kernel pointer independent
         * of the system buffer before we reference the target process.
         */
        PVOID staging = ExAllocatePoolWithTag(NonPagedPool, copySize, KMEM_POOL_TAG);
        if (staging == NULL) {
            ObDereferenceObject(targetProcess);
            status = STATUS_INSUFFICIENT_RESOURCES;
            break;
        }

        RtlCopyMemory(staging, data, copySize);

        status = MmCopyVirtualMemory(
            PsGetCurrentProcess(),  /* source process (kernel staging buf) */
            staging,                /* source address                       */
            targetProcess,          /* destination process                  */
            addr,                   /* destination address                  */
            copySize,
            KernelMode,
            &transferred
        );

        ObDereferenceObject(targetProcess);
        ExFreePoolWithTag(staging, KMEM_POOL_TAG);
        break;
    }

    /* ------------------------------------------------------------------ */
    default:
        status = STATUS_INVALID_DEVICE_REQUEST;
        break;
    }

    Irp->IoStatus.Status      = status;
    Irp->IoStatus.Information = NT_SUCCESS(status) ? transferred : 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return status;
}

/* ── DriverEntry ───────────────────────────────────────────────────────── */

NTSTATUS
DriverEntry(
    _In_ PDRIVER_OBJECT  DriverObject,
    _In_ PUNICODE_STRING RegistryPath
)
{
    UNREFERENCED_PARAMETER(RegistryPath);

    UNICODE_STRING devName = RTL_CONSTANT_STRING(DEVICE_NAME);
    UNICODE_STRING symlink = RTL_CONSTANT_STRING(SYMLINK_NAME);
    NTSTATUS status;

    status = IoCreateDevice(
        DriverObject,
        0,
        &devName,
        FILE_DEVICE_UNKNOWN,
        FILE_DEVICE_SECURE_OPEN,
        FALSE,          /* not exclusive */
        &g_DeviceObject
    );
    if (!NT_SUCCESS(status)) return status;

    status = IoCreateSymbolicLink(&symlink, &devName);
    if (!NT_SUCCESS(status)) {
        IoDeleteDevice(g_DeviceObject);
        g_DeviceObject = NULL;
        return status;
    }

    DriverObject->DriverUnload                          = KMemUnloadVoid;
    DriverObject->MajorFunction[IRP_MJ_CREATE]         = KMemCreateClose;
    DriverObject->MajorFunction[IRP_MJ_CLOSE]          = KMemCreateClose;
    DriverObject->MajorFunction[IRP_MJ_DEVICE_CONTROL] = KMemDeviceControl;

    /* METHOD_BUFFERED does not need DO_BUFFERED_IO; clear the init flag. */
    g_DeviceObject->Flags &= ~DO_DEVICE_INITIALIZING;

    return STATUS_SUCCESS;
}

/*
 * kmem.c — WDM kernel driver (Windows, C)
 *
 * Exposes \\.\KMem and services two IOCTLs:
 *
 *   IOCTL_KMEM_READ   copy bytes FROM a caller-chosen VA range INTO the
 *                     caller's output buffer.
 *
 *   IOCTL_KMEM_WRITE  copy bytes FROM the caller's buffer INTO a caller-
 *                     chosen VA range.
 *
 * Both IOCTLs accept a KMEM_REQUEST header that names the target process
 * (by PID) and the base virtual address.  PID 0 means the kernel address
 * space; any other PID is looked up with PsLookupProcessByProcessId and
 * the copy is performed with MmCopyVirtualMemory.
 *
 * Build with the WDK (plain WDM, no WDF):
 *
 *   Sources file:
 *       TARGETNAME  = kmem
 *       TARGETTYPE  = DRIVER
 *       SOURCES     = kmem.c
 *
 *   Or a minimal CMakeLists.txt that calls add_library(kmem SHARED kmem.c)
 *   with the kernel compile flags set by the WDK toolchain file.
 */

#include <ntddk.h>
#include <wdm.h>

/* ------------------------------------------------------------------ */
/* Device / symbolic-link names                                        */
/* ------------------------------------------------------------------ */

#define DEVICE_NAME  L"\\Device\\KMem"
#define SYMLINK_NAME L"\\DosDevices\\KMem"

/* ------------------------------------------------------------------ */
/* IOCTL codes                                                         */
/*                                                                     */
/* METHOD_BUFFERED: the I/O manager allocates one kernel buffer whose  */
/* size is max(InputBufferLength, OutputBufferLength).  The input data */
/* is copied into it before dispatch and up to Irp->IoStatus.Information */
/* bytes are copied out of it back to the caller after completion.     */
/* ------------------------------------------------------------------ */

#define IOCTL_KMEM_READ  \
    CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_KMEM_WRITE \
    CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)

/* ------------------------------------------------------------------ */
/* Hard cap on a single request (64 MB).                               */
/* ------------------------------------------------------------------ */
#define KMEM_MAX_TRANSFER ((SIZE_T)(64 * 1024 * 1024))

/* ------------------------------------------------------------------ */
/* Shared user/kernel request header                                   */
/* ------------------------------------------------------------------ */
#pragma pack(push, 1)
typedef struct _KMEM_REQUEST {
    ULONG64 ProcessId;  /* target PID; 0 = kernel address space       */
    ULONG64 Address;    /* base virtual address in target space        */
    ULONG64 Size;       /* byte count to read or write                 */
    /*
     * IOCTL_KMEM_WRITE:  data payload immediately follows this header
     *                    inside the input buffer.
     * IOCTL_KMEM_READ:   no extra input bytes; output buffer receives
     *                    the raw bytes read.
     */
} KMEM_REQUEST, *PKMEM_REQUEST;
#pragma pack(pop)

/* ------------------------------------------------------------------ */
/* MmCopyVirtualMemory — undocumented export, stable since XP SP2.    */
/* Used by NtReadVirtualMemory / NtWriteVirtualMemory internally.      */
/* ------------------------------------------------------------------ */
NTKERNELAPI
NTSTATUS
MmCopyVirtualMemory(
    _In_  PEPROCESS       FromProcess,
    _In_  PVOID           FromAddress,
    _In_  PEPROCESS       ToProcess,
    _Out_ PVOID           ToAddress,
    _In_  SIZE_T          BufferSize,
    _In_  KPROCESSOR_MODE PreviousMode,
    _Out_ PSIZE_T         NumberOfBytesCopied
);

/* ------------------------------------------------------------------ */
/* Globals                                                             */
/* ------------------------------------------------------------------ */
static PDEVICE_OBJECT g_Device = NULL;

/* ------------------------------------------------------------------ */
/* KMemCopy                                                            */
/*                                                                     */
/* Unified read/write helper.  bWrite == TRUE means copy LocalBuffer  */
/* → target address space; FALSE means copy target → LocalBuffer.     */
/* ------------------------------------------------------------------ */
static NTSTATUS
KMemCopy(
    _In_  ULONG64 TargetPid,
    _In_  ULONG64 TargetAddress,
    _In_  PVOID   LocalBuffer,
    _In_  SIZE_T  Size,
    _In_  BOOLEAN bWrite
)
{
    NTSTATUS  Status;
    PEPROCESS TargetProcess;
    PEPROCESS Self;
    SIZE_T    Copied;

    if (Size == 0 || Size > KMEM_MAX_TRANSFER) {
        return STATUS_INVALID_BUFFER_SIZE;
    }

    if (TargetPid == 0) {
        /*
         * Kernel VA: guard with SEH — the caller chose the address;
         * we must not bugcheck on a bad pointer.
         */
        __try {
            if (bWrite) {
                RtlCopyMemory((PVOID)(ULONG_PTR)TargetAddress,
                              LocalBuffer, Size);
            } else {
                RtlCopyMemory(LocalBuffer,
                              (PVOID)(ULONG_PTR)TargetAddress, Size);
            }
            Status = STATUS_SUCCESS;
        }
        __except (EXCEPTION_EXECUTE_HANDLER) {
            Status = GetExceptionCode();
        }
        return Status;
    }

    /* User process: look up the EPROCESS, then copy across spaces. */
    Status = PsLookupProcessByProcessId(
        (HANDLE)(ULONG_PTR)TargetPid, &TargetProcess);
    if (!NT_SUCCESS(Status)) {
        return Status;
    }

    Self = PsGetCurrentProcess();

    if (bWrite) {
        Status = MmCopyVirtualMemory(
            Self,                              /* from: our pool buffer */
            LocalBuffer,
            TargetProcess,                     /* to:   target process  */
            (PVOID)(ULONG_PTR)TargetAddress,
            Size, KernelMode, &Copied);
    } else {
        Status = MmCopyVirtualMemory(
            TargetProcess,                     /* from: target process  */
            (PVOID)(ULONG_PTR)TargetAddress,
            Self,                              /* to:   our pool buffer */
            LocalBuffer,
            Size, KernelMode, &Copied);
    }

    ObDereferenceObject(TargetProcess);
    return Status;
}

/* ------------------------------------------------------------------ */
/* IRP_MJ_CREATE / IRP_MJ_CLOSE                                       */
/* ------------------------------------------------------------------ */
static NTSTATUS
KMemCreateClose(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp
)
{
    UNREFERENCED_PARAMETER(DeviceObject);
    Irp->IoStatus.Status      = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

/* ------------------------------------------------------------------ */
/* IRP_MJ_DEVICE_CONTROL                                              */
/* ------------------------------------------------------------------ */
static NTSTATUS
KMemDeviceControl(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp
)
{
    PIO_STACK_LOCATION Stack;
    NTSTATUS           Status;
    ULONG_PTR          Info;
    ULONG              Code;
    ULONG              InLen;
    ULONG              OutLen;
    PVOID              SysBuf;
    PKMEM_REQUEST      Req;
    SIZE_T             DataSize;
    SIZE_T             HeaderSize;

    UNREFERENCED_PARAMETER(DeviceObject);

    Status    = STATUS_INVALID_PARAMETER;
    Info      = 0;
    HeaderSize = sizeof(KMEM_REQUEST);

    Stack  = IoGetCurrentIrpStackLocation(Irp);
    Code   = Stack->Parameters.DeviceIoControl.IoControlCode;
    InLen  = Stack->Parameters.DeviceIoControl.InputBufferLength;
    OutLen = Stack->Parameters.DeviceIoControl.OutputBufferLength;
    SysBuf = Irp->AssociatedIrp.SystemBuffer;

    if (SysBuf == NULL) {
        Status = STATUS_INVALID_PARAMETER;
        goto Complete;
    }

    switch (Code) {

    /* -------------------------------------------------------------- */
    case IOCTL_KMEM_READ:
    /*
     * In:  KMEM_REQUEST describing target {PID, Address, Size}
     * Out: Size raw bytes from [Address, Address + Size)
     *
     * Both in and out share SystemBuffer (METHOD_BUFFERED).
     * We read the header first, then overwrite SystemBuffer[0..Size-1]
     * with the fetched bytes.  The I/O manager copies those back to the
     * caller's output buffer on completion.
     */
        if (InLen < (ULONG)HeaderSize) {
            Status = STATUS_BUFFER_TOO_SMALL;
            break;
        }
        Req      = (PKMEM_REQUEST)SysBuf;
        DataSize = (SIZE_T)Req->Size;

        if (DataSize == 0 || DataSize > KMEM_MAX_TRANSFER) {
            Status = STATUS_INVALID_BUFFER_SIZE;
            break;
        }
        if ((ULONG)DataSize > OutLen) {
            Status = STATUS_BUFFER_TOO_SMALL;
            break;
        }

        /*
         * Save request fields before KMemCopy overwrites SystemBuffer.
         */
        {
            ULONG64 Pid     = Req->ProcessId;
            ULONG64 Address = Req->Address;

            Status = KMemCopy(Pid, Address, SysBuf, DataSize, FALSE);
            if (NT_SUCCESS(Status)) {
                Info = (ULONG_PTR)DataSize;
            }
        }
        break;

    /* -------------------------------------------------------------- */
    case IOCTL_KMEM_WRITE:
    /*
     * In:  KMEM_REQUEST header + data payload
     * Out: nothing
     *
     * Layout of the input buffer:
     *   [0 .. sizeof(KMEM_REQUEST)-1]  header
     *   [sizeof(KMEM_REQUEST) .. +Size-1]  bytes to write
     */
        if (InLen < (ULONG)HeaderSize) {
            Status = STATUS_BUFFER_TOO_SMALL;
            break;
        }
        Req      = (PKMEM_REQUEST)SysBuf;
        DataSize = (SIZE_T)Req->Size;

        if (DataSize == 0 || DataSize > KMEM_MAX_TRANSFER) {
            Status = STATUS_INVALID_BUFFER_SIZE;
            break;
        }

        /* Overflow-safe size check: HeaderSize + DataSize <= InLen */
        if (DataSize > (SIZE_T)(InLen - HeaderSize)) {
            Status = STATUS_BUFFER_TOO_SMALL;
            break;
        }

        {
            ULONG64 Pid     = Req->ProcessId;
            ULONG64 Address = Req->Address;
            PVOID   Data    = (PUCHAR)SysBuf + HeaderSize;

            Status = KMemCopy(Pid, Address, Data, DataSize, TRUE);
        }
        break;

    /* -------------------------------------------------------------- */
    default:
        Status = STATUS_INVALID_DEVICE_REQUEST;
        break;
    }

Complete:
    Irp->IoStatus.Status      = Status;
    Irp->IoStatus.Information = Info;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return Status;
}

/* ------------------------------------------------------------------ */
/* DriverUnload                                                        */
/* ------------------------------------------------------------------ */
static VOID
KMemUnload(
    _In_ PDRIVER_OBJECT DriverObject
)
{
    UNICODE_STRING Sym = RTL_CONSTANT_STRING(SYMLINK_NAME);

    UNREFERENCED_PARAMETER(DriverObject);

    IoDeleteSymbolicLink(&Sym);

    if (g_Device != NULL) {
        IoDeleteDevice(g_Device);
        g_Device = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* DriverEntry                                                         */
/* ------------------------------------------------------------------ */
NTSTATUS
DriverEntry(
    _In_ PDRIVER_OBJECT  DriverObject,
    _In_ PUNICODE_STRING RegistryPath
)
{
    NTSTATUS       Status;
    UNICODE_STRING DevName = RTL_CONSTANT_STRING(DEVICE_NAME);
    UNICODE_STRING Sym     = RTL_CONSTANT_STRING(SYMLINK_NAME);

    UNREFERENCED_PARAMETER(RegistryPath);

    /* Create the device object. */
    Status = IoCreateDevice(
        DriverObject,
        0,
        &DevName,
        FILE_DEVICE_UNKNOWN,
        FILE_DEVICE_SECURE_OPEN,
        FALSE,
        &g_Device
    );
    if (!NT_SUCCESS(Status)) {
        return Status;
    }

    /* Both IOCTLs use METHOD_BUFFERED → set DO_BUFFERED_IO. */
    g_Device->Flags |= DO_BUFFERED_IO;
    g_Device->Flags &= ~DO_DEVICE_INITIALIZING;

    /* Expose the Win32-visible path: \\.\KMem */
    Status = IoCreateSymbolicLink(&Sym, &DevName);
    if (!NT_SUCCESS(Status)) {
        IoDeleteDevice(g_Device);
        g_Device = NULL;
        return Status;
    }

    DriverObject->DriverUnload                         = KMemUnload;
    DriverObject->MajorFunction[IRP_MJ_CREATE]         = KMemCreateClose;
    DriverObject->MajorFunction[IRP_MJ_CLOSE]          = KMemCreateClose;
    DriverObject->MajorFunction[IRP_MJ_DEVICE_CONTROL] = KMemDeviceControl;

    return STATUS_SUCCESS;
}

/*
 * kmem.c — Windows kernel driver (WDM)
 *
 * Maps a caller-supplied user-mode buffer and services IOCTL-based
 * read/write requests for an arbitrary virtual address range chosen
 * by the caller.
 *
 * Build environment: WDK 10, C, x64 target.
 *
 * IOCTL codes (METHOD_BUFFERED, FILE_ANY_ACCESS):
 *   IOCTL_KMEM_READ   0x222004
 *   IOCTL_KMEM_WRITE  0x222008
 *
 * Request layout (input buffer for both IOCTLs):
 *   KMEM_REQUEST  {
 *       ULONG64  Address;   // target virtual address (source for read,
 *                           // destination for write)
 *       ULONG64  Length;    // byte count
 *       // For WRITE the payload immediately follows in the input buffer.
 *   }
 *
 * For READ  the driver copies Length bytes from Address into the output
 *           buffer.
 * For WRITE the driver copies the payload (input buffer after the header)
 *           to Address.
 *
 * Safety notes
 * ============
 *  - MmProbeAndLockPages / MmGetSystemAddressForMdlSafe are used so the
 *    driver never touches user pages without pinning them.
 *  - ProbeForRead / ProbeForWrite guard every access to caller-supplied
 *    addresses.
 *  - __try / __except (EXCEPTION_EXECUTE_HANDLER) wraps all VA-range
 *    accesses; faults return STATUS_ACCESS_VIOLATION to user-mode.
 *  - Length is capped at KMEM_MAX_TRANSFER_BYTES to bound MDL size.
 */

#include <ntddk.h>
#include <wdm.h>

/* -----------------------------------------------------------------------
 * Constants
 * ----------------------------------------------------------------------- */

#define KMEM_DEVICE_NAME      L"\\Device\\KMem"
#define KMEM_SYMLINK_NAME     L"\\DosDevices\\KMem"

#define KMEM_IOCTL(n)  CTL_CODE(FILE_DEVICE_UNKNOWN, (n), METHOD_BUFFERED, \
                                 FILE_ANY_ACCESS)
#define IOCTL_KMEM_READ    KMEM_IOCTL(0x801)
#define IOCTL_KMEM_WRITE   KMEM_IOCTL(0x802)

/* Maximum bytes per single transfer (16 MiB). */
#define KMEM_MAX_TRANSFER_BYTES  (16ULL * 1024 * 1024)

/* -----------------------------------------------------------------------
 * Public request structure (also used as the input buffer header).
 * -----------------------------------------------------------------------
 * Both structures must be kept in sync with the user-mode client.
 */
#pragma pack(push, 1)
typedef struct _KMEM_REQUEST {
    ULONG64 Address;   /* Target virtual address                        */
    ULONG64 Length;    /* Byte count                                     */
    /* For IOCTL_KMEM_WRITE, payload bytes follow immediately here.     */
} KMEM_REQUEST, *PKMEM_REQUEST;
#pragma pack(pop)

/* -----------------------------------------------------------------------
 * Driver globals
 * ----------------------------------------------------------------------- */

static PDEVICE_OBJECT g_DeviceObject = NULL;

/* -----------------------------------------------------------------------
 * Forward declarations
 * ----------------------------------------------------------------------- */

DRIVER_UNLOAD       KMemUnload;
DRIVER_DISPATCH     KMemCreateClose;
DRIVER_DISPATCH     KMemDeviceControl;

static NTSTATUS KMemRead(ULONG64 Address, ULONG64 Length,
                         PVOID OutputBuffer, ULONG OutputLength,
                         PULONG_PTR BytesReturned);

static NTSTATUS KMemWrite(ULONG64 Address, ULONG64 Length,
                          PVOID Payload, ULONG PayloadLength);

/* -----------------------------------------------------------------------
 * DriverEntry
 * ----------------------------------------------------------------------- */

NTSTATUS
DriverEntry(
    _In_  PDRIVER_OBJECT  DriverObject,
    _In_  PUNICODE_STRING RegistryPath
)
{
    UNREFERENCED_PARAMETER(RegistryPath);

    NTSTATUS        status;
    UNICODE_STRING  devName, linkName;

    RtlInitUnicodeString(&devName,  KMEM_DEVICE_NAME);
    RtlInitUnicodeString(&linkName, KMEM_SYMLINK_NAME);

    /* Create the device object. */
    status = IoCreateDevice(
        DriverObject,
        0,                      /* No device extension data needed       */
        &devName,
        FILE_DEVICE_UNKNOWN,
        FILE_DEVICE_SECURE_OPEN,
        FALSE,
        &g_DeviceObject
    );
    if (!NT_SUCCESS(status)) {
        KdPrint(("KMem: IoCreateDevice failed 0x%08X\n", status));
        return status;
    }

    /* Expose a symbolic link to Win32 namespace. */
    status = IoCreateSymbolicLink(&linkName, &devName);
    if (!NT_SUCCESS(status)) {
        KdPrint(("KMem: IoCreateSymbolicLink failed 0x%08X\n", status));
        IoDeleteDevice(g_DeviceObject);
        g_DeviceObject = NULL;
        return status;
    }

    /* METHOD_BUFFERED — no special flag needed; DO_BUFFERED_IO is implied
     * by default for buffered IOCTLs, but set it explicitly for clarity. */
    g_DeviceObject->Flags |= DO_BUFFERED_IO;
    g_DeviceObject->Flags &= ~DO_DEVICE_INITIALIZING;

    /* Wire dispatch routines. */
    DriverObject->MajorFunction[IRP_MJ_CREATE]         = KMemCreateClose;
    DriverObject->MajorFunction[IRP_MJ_CLOSE]          = KMemCreateClose;
    DriverObject->MajorFunction[IRP_MJ_DEVICE_CONTROL] = KMemDeviceControl;
    DriverObject->DriverUnload                         = KMemUnload;

    KdPrint(("KMem: loaded\n"));
    return STATUS_SUCCESS;
}

/* -----------------------------------------------------------------------
 * KMemUnload
 * ----------------------------------------------------------------------- */

VOID
KMemUnload(
    _In_ PDRIVER_OBJECT DriverObject
)
{
    UNICODE_STRING linkName;
    RtlInitUnicodeString(&linkName, KMEM_SYMLINK_NAME);
    IoDeleteSymbolicLink(&linkName);

    if (g_DeviceObject) {
        IoDeleteDevice(g_DeviceObject);
        g_DeviceObject = NULL;
    }

    KdPrint(("KMem: unloaded\n"));
    UNREFERENCED_PARAMETER(DriverObject);
}

/* -----------------------------------------------------------------------
 * KMemCreateClose — trivially succeed open / close
 * ----------------------------------------------------------------------- */

NTSTATUS
KMemCreateClose(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp
)
{
    UNREFERENCED_PARAMETER(DeviceObject);

    Irp->IoStatus.Status      = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

/* -----------------------------------------------------------------------
 * KMemDeviceControl — dispatch IOCTL_KMEM_READ / IOCTL_KMEM_WRITE
 * ----------------------------------------------------------------------- */

NTSTATUS
KMemDeviceControl(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp
)
{
    UNREFERENCED_PARAMETER(DeviceObject);

    PIO_STACK_LOCATION  stack         = IoGetCurrentIrpStackLocation(Irp);
    ULONG               code          = stack->Parameters.DeviceIoControl.IoControlCode;
    ULONG               inputLen      = stack->Parameters.DeviceIoControl.InputBufferLength;
    ULONG               outputLen     = stack->Parameters.DeviceIoControl.OutputBufferLength;

    /* METHOD_BUFFERED: both buffers share Irp->AssociatedIrp.SystemBuffer. */
    PVOID               systemBuffer  = Irp->AssociatedIrp.SystemBuffer;

    NTSTATUS            status        = STATUS_INVALID_DEVICE_REQUEST;
    ULONG_PTR           information   = 0;

    switch (code) {

    /* ------------------------------------------------------------------ */
    case IOCTL_KMEM_READ:
    {
        if (inputLen < sizeof(KMEM_REQUEST)) {
            status = STATUS_BUFFER_TOO_SMALL;
            break;
        }

        PKMEM_REQUEST req = (PKMEM_REQUEST)systemBuffer;
        ULONG64 addr   = req->Address;
        ULONG64 length = req->Length;

        if (length == 0 || length > KMEM_MAX_TRANSFER_BYTES) {
            status = STATUS_INVALID_PARAMETER;
            break;
        }
        if (outputLen < (ULONG)length) {
            status = STATUS_BUFFER_TOO_SMALL;
            break;
        }

        status = KMemRead(addr, length, systemBuffer,
                          outputLen, &information);
        break;
    }

    /* ------------------------------------------------------------------ */
    case IOCTL_KMEM_WRITE:
    {
        /* Input buffer = KMEM_REQUEST header + payload bytes. */
        if (inputLen <= sizeof(KMEM_REQUEST)) {
            status = STATUS_BUFFER_TOO_SMALL;
            break;
        }

        PKMEM_REQUEST req     = (PKMEM_REQUEST)systemBuffer;
        ULONG64       addr    = req->Address;
        ULONG64       length  = req->Length;
        ULONG         payloadOffset = sizeof(KMEM_REQUEST);
        ULONG         payloadLen    = inputLen - payloadOffset;

        if (length == 0 || length > KMEM_MAX_TRANSFER_BYTES) {
            status = STATUS_INVALID_PARAMETER;
            break;
        }
        if ((ULONG64)payloadLen < length) {
            status = STATUS_BUFFER_TOO_SMALL;
            break;
        }

        PVOID payload = (PUCHAR)systemBuffer + payloadOffset;
        status = KMemWrite(addr, length, payload, payloadLen);
        if (NT_SUCCESS(status)) {
            information = (ULONG_PTR)length;
        }
        break;
    }

    /* ------------------------------------------------------------------ */
    default:
        status = STATUS_INVALID_DEVICE_REQUEST;
        break;
    }

    Irp->IoStatus.Status      = status;
    Irp->IoStatus.Information = information;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return status;
}

/* -----------------------------------------------------------------------
 * KMemRead
 *
 * Pins [Address, Address+Length) with an MDL, maps it to a system-space
 * address, then copies into OutputBuffer.
 *
 * Returns STATUS_SUCCESS and sets *BytesReturned on success.
 * ----------------------------------------------------------------------- */

static NTSTATUS
KMemRead(
    _In_  ULONG64      Address,
    _In_  ULONG64      Length,
    _Out_ PVOID        OutputBuffer,
    _In_  ULONG        OutputLength,
    _Out_ PULONG_PTR   BytesReturned
)
{
    NTSTATUS status = STATUS_SUCCESS;
    *BytesReturned  = 0;

    /* Reject length values that overflow SIZE_T on the current platform. */
    if (Length > (ULONG64)MAXSIZE_T) {
        return STATUS_INVALID_PARAMETER;
    }

    PVOID  srcVa = (PVOID)(ULONG_PTR)Address;
    SIZE_T len   = (SIZE_T)Length;

    __try {
        ProbeForRead(srcVa, len, 1);
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        return STATUS_ACCESS_VIOLATION;
    }

    PMDL mdl = IoAllocateMdl(srcVa, (ULONG)len, FALSE, FALSE, NULL);
    if (!mdl) {
        return STATUS_INSUFFICIENT_RESOURCES;
    }

    __try {
        MmProbeAndLockPages(mdl, KernelMode, IoReadAccess);
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        IoFreeMdl(mdl);
        return STATUS_ACCESS_VIOLATION;
    }

    PVOID mappedVa = MmGetSystemAddressForMdlSafe(mdl, NormalPagePriority |
                                                        MdlMappingNoExecute);
    if (!mappedVa) {
        MmUnlockPages(mdl);
        IoFreeMdl(mdl);
        return STATUS_INSUFFICIENT_RESOURCES;
    }

    __try {
        RtlCopyMemory(OutputBuffer, mappedVa, len);
        *BytesReturned = (ULONG_PTR)len;
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        status = STATUS_ACCESS_VIOLATION;
    }

    MmUnlockPages(mdl);
    IoFreeMdl(mdl);
    UNREFERENCED_PARAMETER(OutputLength); /* already validated by caller */
    return status;
}

/* -----------------------------------------------------------------------
 * KMemWrite
 *
 * Pins [Address, Address+Length) with an MDL (write access), maps it,
 * copies the payload bytes.
 * ----------------------------------------------------------------------- */

static NTSTATUS
KMemWrite(
    _In_ ULONG64  Address,
    _In_ ULONG64  Length,
    _In_ PVOID    Payload,
    _In_ ULONG    PayloadLength
)
{
    NTSTATUS status = STATUS_SUCCESS;

    if (Length > (ULONG64)MAXSIZE_T) {
        return STATUS_INVALID_PARAMETER;
    }

    PVOID  dstVa = (PVOID)(ULONG_PTR)Address;
    SIZE_T len   = (SIZE_T)Length;

    __try {
        ProbeForWrite(dstVa, len, 1);
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        return STATUS_ACCESS_VIOLATION;
    }

    PMDL mdl = IoAllocateMdl(dstVa, (ULONG)len, FALSE, FALSE, NULL);
    if (!mdl) {
        return STATUS_INSUFFICIENT_RESOURCES;
    }

    __try {
        MmProbeAndLockPages(mdl, KernelMode, IoWriteAccess);
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        IoFreeMdl(mdl);
        return STATUS_ACCESS_VIOLATION;
    }

    PVOID mappedVa = MmGetSystemAddressForMdlSafe(mdl, NormalPagePriority |
                                                        MdlMappingNoExecute);
    if (!mappedVa) {
        MmUnlockPages(mdl);
        IoFreeMdl(mdl);
        return STATUS_INSUFFICIENT_RESOURCES;
    }

    __try {
        RtlCopyMemory(mappedVa, Payload, len);
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        status = STATUS_ACCESS_VIOLATION;
    }

    MmUnlockPages(mdl);
    IoFreeMdl(mdl);
    UNREFERENCED_PARAMETER(PayloadLength); /* validated by caller */
    return status;
}

/*
 * kmem.c - Windows kernel driver: user buffer mapping + virtual address range read/write
 *
 * TODO: Implement full IRP dispatch, symbolic link, and device cleanup.
 *
 * Build: WDK, compile as kernel-mode driver (C).
 */

#include <ntddk.h>
#include <wdm.h>

/* -----------------------------------------------------------------------
 * IOCTL codes
 * ----------------------------------------------------------------------- */
#define KMEM_DEVICE_TYPE    0x8000
#define IOCTL_KMEM_READ     CTL_CODE(KMEM_DEVICE_TYPE, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_KMEM_WRITE    CTL_CODE(KMEM_DEVICE_TYPE, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)

/* -----------------------------------------------------------------------
 * Request structures (shared with user-mode caller)
 * ----------------------------------------------------------------------- */
#pragma pack(push, 1)
typedef struct _KMEM_REQUEST {
    ULONG_PTR TargetVa;   /* virtual address in the target process */
    SIZE_T    Length;     /* bytes to transfer                     */
    /* For READ:  output follows immediately in the output buffer.
       For WRITE: data to write follows immediately in the input buffer
                  after this header.                                     */
} KMEM_REQUEST, *PKMEM_REQUEST;
#pragma pack(pop)

/* -----------------------------------------------------------------------
 * Forward declarations
 * ----------------------------------------------------------------------- */
DRIVER_UNLOAD       KmemUnload;
DRIVER_DISPATCH     KmemCreate;
DRIVER_DISPATCH     KmemClose;
DRIVER_DISPATCH     KmemDeviceControl;

static UNICODE_STRING g_DeviceName  = RTL_CONSTANT_STRING(L"\\Device\\KmemDrv");
static UNICODE_STRING g_SymlinkName = RTL_CONSTANT_STRING(L"\\DosDevices\\KmemDrv");

/* -----------------------------------------------------------------------
 * DriverEntry
 * ----------------------------------------------------------------------- */
NTSTATUS
DriverEntry(
    _In_ PDRIVER_OBJECT  DriverObject,
    _In_ PUNICODE_STRING RegistryPath)
{
    NTSTATUS       status;
    PDEVICE_OBJECT deviceObject = NULL;

    UNREFERENCED_PARAMETER(RegistryPath);

    /* Create the device object. */
    status = IoCreateDevice(
        DriverObject,
        0,
        &g_DeviceName,
        FILE_DEVICE_UNKNOWN,
        FILE_DEVICE_SECURE_OPEN,
        FALSE,
        &deviceObject);

    if (!NT_SUCCESS(status)) {
        return status;
    }

    /* Expose a user-mode accessible symbolic link. */
    status = IoCreateSymbolicLink(&g_SymlinkName, &g_DeviceName);
    if (!NT_SUCCESS(status)) {
        IoDeleteDevice(deviceObject);
        return status;
    }

    /* Wire up dispatch routines. */
    DriverObject->MajorFunction[IRP_MJ_CREATE]         = KmemCreate;
    DriverObject->MajorFunction[IRP_MJ_CLOSE]          = KmemClose;
    DriverObject->MajorFunction[IRP_MJ_DEVICE_CONTROL] = KmemDeviceControl;
    DriverObject->DriverUnload                         = KmemUnload;

    /* METHOD_BUFFERED: the I/O manager handles the copy in/out. */
    deviceObject->Flags |= DO_BUFFERED_IO;
    deviceObject->Flags &= ~DO_DEVICE_INITIALIZING;

    return STATUS_SUCCESS;
}

/* -----------------------------------------------------------------------
 * KmemUnload
