/* -----------------------------------------------------------------------
 * KmemMapAndTransfer
 *
 * Maps [TargetVa, TargetVa+Length) from the calling process into a kernel
 * MDL and either copies to or from KernelBuffer.
 *
 * isWrite == FALSE  =>  read from user VA  into KernelBuffer
 * isWrite == TRUE   =>  write from KernelBuffer into user VA
 * ----------------------------------------------------------------------- */
static NTSTATUS
KmemMapAndTransfer(
    _In_    ULONG_PTR  TargetVa,
    _In_    SIZE_T     Length,
    _Inout_ PVOID      KernelBuffer,
    _In_    BOOLEAN    isWrite)
{
    NTSTATUS  status  = STATUS_SUCCESS;
    PMDL      mdl     = NULL;
    PVOID     mapped  = NULL;

    /* Sanity-check: refuse zero-length or obviously bogus requests. */
    if (Length == 0 || Length > 64 * 1024 * 1024ULL) {
        return STATUS_INVALID_PARAMETER;
    }

    /* Allocate an MDL describing the user-mode buffer.
     * IoAllocateMdl does NOT lock pages; we do that next. */
    mdl = IoAllocateMdl((PVOID)(ULONG_PTR)TargetVa, (ULONG)Length,
                        FALSE, FALSE, NULL);
    if (!mdl) {
        return STATUS_INSUFFICIENT_RESOURCES;
    }

    /* Lock the pages into physical memory.
     * We run at PASSIVE_LEVEL (IOCTL path) so this is legal. */
    __try {
        MmProbeAndLockPages(mdl,
                            UserMode,
                            isWrite ? IoWriteAccess : IoReadAccess);
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        IoFreeMdl(mdl);
        return STATUS_ACCESS_VIOLATION;
    }

    /* Map the locked pages into kernel virtual address space. */
    mapped = MmGetSystemAddressForMdlSafe(mdl, NormalPagePriority |
                                               MdlMappingNoExecute);
    if (!mapped) {
        MmUnlockPages(mdl);
        IoFreeMdl(mdl);
        return STATUS_INSUFFICIENT_RESOURCES;
    }

    /* Perform the transfer. */
    __try {
        if (!isWrite) {
            /* READ: user VA -> kernel buffer */
            RtlCopyMemory(KernelBuffer, mapped, Length);
        } else {
            /* WRITE: kernel buffer -> user VA */
            RtlCopyMemory(mapped, KernelBuffer, Length);
        }
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        status = STATUS_ACCESS_VIOLATION;
    }

    /* Clean up: unmap, unlock, free the MDL. */
    MmUnmapLockedPages(mapped, mdl);
    MmUnlockPages(mdl);
    IoFreeMdl(mdl);

    return status;
}

/* -----------------------------------------------------------------------
 * KmemDeviceControl  –  IOCTL dispatcher
 * ----------------------------------------------------------------------- */
NTSTATUS
KmemDeviceControl(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp)
{
    NTSTATUS            status;
    PIO_STACK_LOCATION  stack;
    ULONG               controlCode;
    PVOID               sysBuffer;      /* METHOD_BUFFERED shared buffer     */
    ULONG               inputLength;
    ULONG               outputLength;
    PKMEM_REQUEST       req;
    PVOID               dataBuf = NULL;
    ULONG               dataLen;

    UNREFERENCED_PARAMETER(DeviceObject);

    stack         = IoGetCurrentIrpStackLocation(Irp);
    controlCode   = stack->Parameters.DeviceIoControl.IoControlCode;
    sysBuffer     = Irp->AssociatedIrp.SystemBuffer;
    inputLength   = stack->Parameters.DeviceIoControl.InputBufferLength;
    outputLength  = stack->Parameters.DeviceIoControl.OutputBufferLength;

    Irp->IoStatus.Information = 0;

    switch (controlCode) {

    /* ------------------------------------------------------------------
     * IOCTL_KMEM_READ
     *
     * Input  (inputLength):  KMEM_REQUEST
     * Output (outputLength): raw bytes read from TargetVa
     * ------------------------------------------------------------------ */
    case IOCTL_KMEM_READ:
    {
        if (inputLength < sizeof(KMEM_REQUEST) || !sysBuffer) {
            status = STATUS_INVALID_PARAMETER;
            break;
        }

        req     = (PKMEM_REQUEST)sysBuffer;
        dataLen = (ULONG)req->Length;

        if (dataLen == 0 || dataLen > outputLength) {
            status = STATUS_INVALID_PARAMETER;
            break;
        }

        /* The output goes straight into the buffered-I/O system buffer. */
        status = KmemMapAndTransfer(req->TargetVa, dataLen,
                                    sysBuffer,  /* reuse for output */
                                    FALSE);

        /*
         * NOTE: for a clean protocol the caller should use a separate
         * output buffer.  Here we write the read data starting at byte 0
         * of sysBuffer (overlapping the request header) which is fine
         * because the header is consumed before the transfer.
         */
        if (NT_SUCCESS(status)) {
            Irp->IoStatus.Information = dataLen;
        }
        break;
    }

    /* ------------------------------------------------------------------
     * IOCTL_KMEM_WRITE
     *
     * Input  (inputLength):  KMEM_REQUEST + data to write
     * Output: none
     * ------------------------------------------------------------------ */
    case IOCTL_KMEM_WRITE:
    {
        if (inputLength <= sizeof(KMEM_REQUEST) || !sysBuffer) {
            status = STATUS_INVALID_PARAMETER;
            break;
        }

        req     = (PKMEM_REQUEST)sysBuffer;
        dataLen = (ULONG)req->Length;

        /* Data immediately follows the header in the input buffer. */
        if (dataLen == 0 ||
            (ULONG)(sizeof(KMEM_REQUEST) + dataLen) > inputLength) {
            status = STATUS_INVALID_PARAMETER;
            break;
        }

        dataBuf = (PUCHAR)sysBuffer + sizeof(KMEM_REQUEST);

        status = KmemMapAndTransfer(req->TargetVa, dataLen,
                                    dataBuf,
                                    TRUE);

        if (NT_SUCCESS(status)) {
            Irp->IoStatus.Information = 0;
        }
        break;
    }

    default:
        status = STATUS_INVALID_DEVICE_REQUEST;
        break;
    }

    Irp->IoStatus.Status = status;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return status;
}

#pragma once
#include <cstdint>

// ---------------------------------------------------------------------------
// aim.h — UE4 head-to-screen projection + smoothed aim delta
//
// CameraData is populated by the caller (from mach_vm_read / Frida on macOS).
// This module owns only the math and EMA state.
// ---------------------------------------------------------------------------

struct Vec2 { float x, y; };
struct Vec3 { float x, y, z; };

// UE4 ViewProjectionMatrix in row-major layout (matches SDK dump order).
// Grab from: PlayerController → PlayerCameraManager → CachedCameraProperties,
// or reconstruct from FMinimalViewInfo (location, rotation, FOV).
struct CameraData {
    float vpm[4][4];  // row-major ViewProjectionMatrix
    float screen_w;   // viewport width  in pixels
    float screen_h;   // viewport height in pixels
};

// Project a UE4 world-space position to screen-space pixels.
// Returns false when the point is behind the near plane (w <= 0).
bool world_to_screen(const Vec3& world, const CameraData& cam, Vec2& out_screen);

// Compute a smoothed crosshair delta toward `head_pos`, filtered to a
// circular cone of `cone_px` pixels around the screen centre.
//
//   cone_px   — radius in pixels; 240.0f matches the requested spec
//   smooth    — EMA factor per tick: 0.0 = frozen, 1.0 = instant snap;
//               values around 0.07–0.15 produce natural-feeling curves
//   out_delta — pixel delta to add to current cursor/aim position
//
// Returns true when head_pos is visible and within the cone.
// Returns false (and leaves out_delta zeroed) when outside the cone or
// behind the camera; also resets internal EMA so the next valid frame
// starts cleanly.
bool aim_delta(const Vec3& head_pos, const CameraData& cam,
               float cone_px, float smooth, Vec2& out_delta);

// Explicitly reset EMA state — call when switching targets or on key-up.
void aim_reset();

#pragma once

#include <cstddef>

// ---------------------------------------------------------------------------
// Minimal UE4 math types
// Guard these if your SDK dump already defines them.
// ---------------------------------------------------------------------------

struct FVector {
    float X = 0.f, Y = 0.f, Z = 0.f;
};

struct FVector2D {
    float X = 0.f, Y = 0.f;
};

// Row-major 4×4, matching UE4's FMatrix memory layout exactly.
struct FMatrix {
    float M[4][4];
};

// ---------------------------------------------------------------------------
// Aim result
// ---------------------------------------------------------------------------

struct AimTarget {
    bool      valid   = false; // false → nothing in cone, do not move crosshair
    FVector2D delta;           // smoothed pixel delta (cx→head) to apply each frame
    float     dist_px = 0.f;  // raw pre-smooth distance from centre to best head
};

// ---------------------------------------------------------------------------
// Frame-rate-independent exponential smoother
// ---------------------------------------------------------------------------

class AimSmoother {
public:
    // smooth_factor in [0, 1).
    //   0.00  → instant snap to raw delta
    //   0.60  → moderate smoothing (good default)
    //   0.90  → heavy humanisation
    explicit AimSmoother(float smooth_factor = 0.60f) noexcept;

    // Feed the raw pixel delta and elapsed seconds; returns the smoothed delta.
    FVector2D update(FVector2D raw_delta, float dt_seconds) noexcept;

    void  reset()                     noexcept;
    void  set_smooth_factor(float f)  noexcept;

private:
    float     smooth_factor_;
    FVector2D current_;
};

// ---------------------------------------------------------------------------
// Core projection helper
// ---------------------------------------------------------------------------

// Returns false when the point is behind the near plane (w < threshold).
bool world_to_screen(
    const FMatrix& vpm,         // pre-multiplied ViewProjectionMatrix
    const FVector& world,
    float          screen_w,
    float          screen_h,
    FVector2D&     out
) noexcept;

// ---------------------------------------------------------------------------
// Main per-frame entry point
// ---------------------------------------------------------------------------

// vpm       : ViewProjectionMatrix captured from UE4 (FSceneView or
//             APlayerCameraManager::GetCameraView).
// screen_w/h: client-area pixel dimensions.
// heads     : world-space head bone positions for each visible entity.
// count     : length of heads[].
// smoother  : caller-owned; keep it alive across frames so the EMA is continuous.
// dt        : frame delta in seconds.
// cone_px   : cone radius in pixels around the screen centre (default 240).
//
// Returns AimTarget. When valid == false let the crosshair idle; the smoother
// is kept warm so it does not jump on the next acquisition.
AimTarget aim_update(
    const FMatrix&  vpm,
    float           screen_w,
    float           screen_h,
    const FVector*  heads,
    std::size_t     count,
    AimSmoother&    smoother,
    float           dt,
    float           cone_px = 240.f
) noexcept;
